(function(root){'use strict';
function series(events,c,metric,from,to){const begin=AB.date(from),finish=AB.date(to),obs=AB.date(c.observation);if(begin===null||finish===null||begin>finish||(finish-begin)/864e5>365)throw Error('Chart cần khoảng ngày hợp lệ, tối đa 366 ngày.');const cohortStart=AB.date(c.from),cohortEnd=AB.date(c.to)+864e5,horizon=c.windowDays*864e5,cutoff=obs+864e5;const {users}=AB.members(events.filter(e=>e.time<cutoff),c.experiment);const eligible=users.filter(u=>u.exposed>=cohortStart&&u.exposed<cohortEnd&&u.exposed+horizon<=cutoff&&Object.entries(c.filters||{}).every(([k,v])=>!v?.length||v.includes(u.dims[k]??'')));const variants=[...new Set(users.map(u=>u.variant))].sort();const buckets=new Map();for(const u of eligible){const days=new Map();for(const e of u.events){if(e.time>=u.exposed+horizon)continue;if(!days.has(e.date))days.set(e.date,[]);days.get(e.date).push(e)}for(let d=begin;d<=finish;d+=864e5){if(u.exposed>=d+864e5||u.exposed+horizon<=d)continue;const date=new Date(d).toISOString().slice(0,10),key=u.variant+'\u0000'+date;if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(AB.value({...u,events:days.get(date)||[]},metric,c.windowDays).v)}}const dates=[];for(let d=begin;d<=finish;d+=864e5)dates.push(new Date(d).toISOString().slice(0,10));return variants.map(variant=>({variant,points:dates.map(date=>({date,...AB.summary(buckets.get(variant+'\u0000'+date)||[],metric.type)}))}))}
const api={series};if(typeof module!=='undefined')module.exports=api;else root.CalendarMetric=api;
})(typeof window!=='undefined'?window:globalThis);
